import{_ as t,o,c as n,j as e,a as r}from"./chunks/framework.Dn6zxbF8.js";const p=JSON.parse('{"title":"Terraform","description":"","frontmatter":{"name":"Terraform","quadrant":"tools","history":[{"edition":"2026.2","ring":"hold"}],"tags":["infrastructure","iac","licensing"]},"headers":[],"relativePath":"radar/items/terraform.md","filePath":"radar/items/terraform.md"}'),s={name:"radar/items/terraform.md"};function i(d,a,c,l,f,m){return o(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"terraform",tabindex:"-1"},[r("Terraform "),e("a",{class:"header-anchor",href:"#terraform","aria-label":'Permalink to "Terraform"'},"​")],-1),e("p",null,[r("Terraform still provisions infrastructure correctly, and the HCL and state model it popularized are the reason "),e("a",{href:"./opentofu.html"},"OpenTofu"),r(" could exist at all. That part of the job was never in question.")],-1),e("p",null,"It is on Hold because HashiCorp stopped granting the license that made adopting it a decision without a counterparty. In August 2023 HashiCorp relicensed Terraform from MPL 2.0 to the Business Source License, a source-available license that restricts competing commercial use and only converts to MPL four years after each version's release. IBM's acquisition of HashiCorp, completed in 2025, adds a second party to that license going forward, not fewer. Depending on Terraform now means depending on one vendor's terms for the tool underneath every other infrastructure decision, which is exactly the provider lock-in a build-on-top choice is supposed to avoid.",-1),e("p",null,"Hold is not a removal order. Infrastructure already provisioned by Terraform is not broken and does not need an emergency migration. New infrastructure should start on OpenTofu, and a module written against one reads against the other with no rewrite, since OpenTofu is a compatible fork of the pre-relicense codebase.",-1)])])}const h=t(s,[["render",i]]);export{p as __pageData,h as default};
